def gaps(intervals, lo, hi):
    if lo > hi:
        raise ValueError
    out = []
    cur = lo
    for start, end in merge(intervals):
        if end <= lo:
            continue
        if start >= hi:
            break
        if start > cur:
            out.append((cur, start))
        if end > cur:
            cur = end
        if cur >= hi:
            break
    if cur < hi:
        out.append((cur, hi))
    return out
```

